    String url = "exchange://127.0.0.4:" + port + "/client.reconnect.test?check=false&" + Constants.RECONNECT_KEY + "=" + //1ms reconnect,保证有足够频率的重连
    1 + "&" + Constants.SHUTDOWN_TIMEOUT_KEY + //shutdown时间足够短，确保error日志输出
    "=1" + //每隔多少warning记录一次
    "&reconnect.waring.period=100";
    try {
        Exchangers.connect(url);
    } catch (Exception e) {
        //do nothing
    }
    int count = 0;
    for (int i = 0; i < 100; i++) {
        count = LogUtil.findMessage(Level.WARN, "client reconnect to ");
        if (count >= 1) {
            break;
        }
        //重连线程的运行
        Thread.sleep(50);
    }
    Assert.assertTrue("warning message count must >= 1, real :" + count, count >= 1);
    DubboAppender.doStop();
}

